  pdf.setTextColor(255,255,255);pdf.setFont('helvetica','bold');pdf.setFontSize(20);pdf.text('OpalMinds',margin,36);pdf.setFontSize(13);pdf.text('Snack History',margin,59);
  pdf.setFont('helvetica','normal');pdf.setFontSize(9);pdf.text(`Date: ${formatReportDate(date)}   |   Records: ${records.length}   |   Total quantity: ${total}`,margin,77);
  y=110;
  const cardGap=10,cardW=(usable-cardGap)/2;
  [['SNACK RECORDS',String(records.length)],['TOTAL QUANTITY',String(total)],['KNOWN EXPENSE',fmtMoney(knownAmount)],['UNPRICED',String(unpriced)]].forEach((metric,i)=>{const cardWidth=(usable-cardGap*3)/4,x=margin+i*(cardWidth+cardGap);pdf.setFillColor(248,250,252);pdf.roundedRect(x,y,cardWidth,44,5,5,'F');pdf.setTextColor(100,116,139);pdf.setFont('helvetica','bold');pdf.setFontSize(6);pdf.text(metric[0],x+8,y+15);pdf.setTextColor(...navy);pdf.setFontSize(metric[1].length>12?8:12);pdf.text(metric[1],x+8,y+34)});
  y+=57;
