  const canvas=document.createElement('canvas');canvas.width=width;canvas.height=1000;const ctx=canvas.getContext('2d');if(!ctx)return reject(new Error('Canvas is not available.'));
  const wrap=(text,maxWidth,font)=>{ctx.font=font;const words=String(text||'').split(/\s+/),lines=[];let line='';for(const word of words){const next=line?`${line} ${word}`:word;if(line&&ctx.measureText(next).width>maxWidth){lines.push(line);line=word}else line=next}if(line)lines.push(line);return lines.length?lines:['']};
  const employeeRows=rows.map(row=>{const lines=wrap(row.snacks.map(item=>`${item.name} x ${item.quantity}`).join('  |  '),employeeCols[2]-28,'17px Arial');return{row,lines,height:Math.max(60,lines.length*23+26)}});
  const employeeTitleY=446,employeeHeadY=470,employeeBodyY=employeeHeadY+employeeHeadH,employeeEnd=employeeBodyY+employeeRows.reduce((sum,item)=>sum+item.height,0),snackTitleY=employeeEnd+52,snackHeadY=snackTitleY+24,snackBodyY=snackHeadY+snackHeadH,snackRowH=60,footerY=snackBodyY+Math.max(1,snackTotals.length)*snackRowH+38,canvasHeight=footerY+60;
  canvas.height=canvasHeight;ctx.fillStyle='#f8fafc';ctx.fillRect(0,0,width,canvasHeight);ctx.fillStyle='#172554';ctx.fillRect(0,0,width,250);ctx.fillStyle='#2563eb';ctx.fillRect(0,242,width,8);ctx.fillStyle='#fff';ctx.font='700 48px Arial';ctx.fillText('OpalMinds',pad,82);ctx.font='600 30px Arial';ctx.fillText(`${breakLabel} - Snacks Report`,pad,135);ctx.font='22px Arial';ctx.fillStyle='#dbeafe';ctx.fillText(`Report period: ${periodLabel}`,pad,184);
  const cards=[['EMPLOYEES',String(employeeCount)],['SNACK RECORDS',String(recordCount)],['TOTAL QUANTITY',String(totalQuantity)],['KNOWN EXPENSES',fmtMoney(totalAmount)],['UNPRICED',String(unpricedRecords)]],gap=16,cardW=(width-pad*2-gap*4)/5;cards.forEach((card,i)=>{const x=pad+i*(cardW+gap);ctx.fillStyle='#fff';ctx.fillRect(x,290,cardW,100);ctx.fillStyle='#64748b';ctx.font='700 15px Arial';ctx.fillText(card[0],x+16,326);ctx.fillStyle=i===2?'#0f766e':'#172554';ctx.font='700 22px Arial';ctx.fillText(card[1],x+16,366,cardW-28)});
  const drawHeader=(y,headers,widths)=>{ctx.fillStyle='#eff6ff';ctx.fillRect(pad,y,width-pad*2,48);ctx.fillStyle='#172554';ctx.font='700 16px Arial';let x=pad;headers.forEach((header,i)=>{ctx.fillText(header,x+12,y+30);x+=widths[i]})};
  ctx.fillStyle='#0f172a';ctx.font='700 27px Arial';ctx.fillText('Employee-wise snack details',pad,employeeTitleY);drawHeader(employeeHeadY,['EMPLOYEE','BREAK','SNACK DETAILS','TOTAL QTY','RECORDS'],employeeCols);
