  ctx.fillStyle='#0f172a';ctx.font='700 27px Arial';ctx.fillText('Break-wise snack totals',pad,snackTitleY);drawHeader(snackHeadY,['BREAK','SNACK','QUANTITY','RECORDS','KNOWN EXPENSE'],snackCols);
  snackTotals.forEach((item,index)=>{const y=snackBodyY+index*snackRowH;ctx.fillStyle=index%2?'#fff':'#f8fafc';ctx.fillRect(pad,y,width-pad*2,snackRowH);const cells=[item.breakType||'Unassigned',item.name,String(item.quantity),String(item.records),fmtMoney(item.amount)];let x=pad;cells.forEach((cell,i)=>{ctx.fillStyle=i===4?'#0f766e':'#334155';ctx.font=i===4?'700 17px Arial':'17px Arial';ctx.fillText(cell,x+12,y+36,snackCols[i]-22);x+=snackCols[i]});ctx.strokeStyle='#e2e8f0';ctx.beginPath();ctx.moveTo(pad,y+snackRowH);ctx.lineTo(width-pad,y+snackRowH);ctx.stroke()});
  ctx.fillStyle='#64748b';ctx.font='16px Arial';ctx.fillText(`${unpricedRecords} records have unknown unit price. Payment status is not tracked.`,pad,footerY);
